def best_trade(prices):
    lo = 0
    best = (0, 0, 0)
    for j in range(1, len(prices)):
        profit = prices[j] - prices[lo]
        if profit > best[2]:
            best = (lo, j, profit)
        if prices[j] < prices[lo]:
            lo = j
    return best
